const images=window.NUZHA_GALLERY||[],filters=document.querySelector("#galleryFilters"),grid=document.querySelector("#galleryGrid"),lightbox=document.querySelector("#lightbox");
let lang=localStorage.getItem("nuzha-lang")||"en",filter="all",activeIndex=0;
const labels={en:{all:"All moments",feasts:"Feasts",dishes:"Dishes",kitchen:"In the kitchen"},ar:{all:"كل الصور",feasts:"الولائم",dishes:"الأطباق",kitchen:"في المطبخ"}};
function applyLanguage(){document.documentElement.lang=lang;document.documentElement.dir=lang==="ar"?"rtl":"ltr";document.querySelector("#langBtn").textContent=lang==="en"?"العربية":"English";document.querySelectorAll("[data-en]").forEach(el=>el.textContent=el.dataset[lang]);render()}
function render(){const cats=["all",...new Set(images.map(x=>x.category))];filters.innerHTML=cats.map(c=>`<button class="filter-btn ${c===filter?'active':''}" data-filter="${c}">${labels[lang][c]||c}</button>`).join("");const visible=images.filter(x=>filter==="all"||x.category===filter);grid.innerHTML=visible.map((x,i)=>`<button class="gallery-item" data-src="${x.src}" data-index="${images.indexOf(x)}"><img src="${x.src}" alt="${lang==='ar'?x.titleAr:x.titleEn}" loading="lazy"><span class="gallery-label">${lang==='ar'?x.titleAr:x.titleEn}</span></button>`).join("");document.querySelector("#emptyGallery").hidden=visible.length>0;filters.querySelectorAll("button").forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});grid.querySelectorAll(".gallery-item").forEach(b=>b.onclick=()=>openLightbox(+b.dataset.index))}
function openLightbox(i){activeIndex=i;const x=images[i];lightboxImage.src=x.src;lightboxImage.alt=lang==='ar'?x.titleAr:x.titleEn;lightboxCaption.textContent=lang==='ar'?x.titleAr:x.titleEn;lightbox.showModal()}
function step(n){activeIndex=(activeIndex+n+images.length)%images.length;openLightbox(activeIndex)}
langBtn.onclick=()=>{lang=lang==="en"?"ar":"en";localStorage.setItem("nuzha-lang",lang);applyLanguage()};themeBtn.onclick=()=>{const order=[null,"theme-night","theme-rose"],active=document.body.classList.contains("theme-night")?1:document.body.classList.contains("theme-rose")?2:0,next=order[(active+1)%3];document.body.classList.remove("theme-night","theme-rose");if(next)document.body.classList.add(next)};document.querySelector(".menu-toggle").onclick=e=>{const n=document.querySelector(".site-header nav");n.classList.toggle("open");e.currentTarget.setAttribute("aria-expanded",n.classList.contains("open"))};lightboxClose.onclick=()=>lightbox.close();lightboxPrev.onclick=()=>step(-1);lightboxNext.onclick=()=>step(1);lightbox.onclick=e=>{if(e.target===lightbox)lightbox.close()};document.addEventListener("keydown",e=>{if(!lightbox.open)return;if(e.key==="ArrowLeft")step(-1);if(e.key==="ArrowRight")step(1)});applyLanguage();
